import styled from "styled-components";


export const ModalWrapper= styled.div`
    width:100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    position:absolute;
    top:0;
    left:0;
    z-index: 9999;
    background: #fff;

    .close{

        width:32px;
        height: 32px;
        position: absolute;
        right:0;
        cursor: pointer;
        background-color:transparent;
        outline:none;
        border:none;
        display:flex;
        top:1rem;
    }
        .close::before{
            content:"";
            position: absolute;
            width:2.5px;
            height:24px;
            background-color:#000;
            transform: rotate(45deg);

        }
        .close::after{
            content:"";
            position: absolute;
            width:2.5px;
            height:24px;
            background-color:#000;
            transform: rotate(-45deg);
        }
    
       

    }

    .content{
        display:flex;
        flex-direction: column;
    }

`


export const ModalButtonContainer= styled.div`
    width:100%;
    display: flex;



`
export const ModalBody= styled.div`
    width:100%;
    display: flex;



`
